$cmd = 'echo SIMDIR; ls -la /sys/devices/platform/cpif/sim; echo DS; cat /sys/devices/platform/cpif/sim/ds_detect 2>/dev/null; echo INFO; ls /sys/devices/platform/cpif/info_region 2>/dev/null | head -30; echo LEGACY; ls /sys/devices/platform/cpif/legacy 2>/dev/null | head -20; echo LOGBUF; ls /dev/logbuffer* /sys/devices/virtual/misc/logbuffer* 2>/dev/null; ls /proc/cp* 2>/dev/null | head; dmesg | grep -iE "Present|Pin1|SIM STATUS|app_state" | tail -n 15; echo STR; grep -aob "SIM STATUS update" /dev/mem 2>/dev/null | head || true'
& 'C:\Users\Admin\Projects\saaios\os\targets\panther\tools\com13.ps1' -Port COM13 -WaitSeconds 25 -Cmd $cmd
